  collections(first: 100, after: $after, query: "published_status:published") {
    pageInfo { hasNextPage endCursor }
    nodes { id handle title descriptionHtml sortOrder productsCount { count }
      ruleSet { appliedDisjunctively rules { column relation condition } }
      keyword: metafield(namespace: $ns, key: "target_keyword") { value }
      volume: metafield(namespace: $ns, key: "keyword_volume") { value } }
  }
  menus(first: 25) {
    nodes { handle items { title resourceId url
      items { title resourceId url items { title resourceId url } } } }
  }
  productVendors(first: 250) { nodes }
}`, variables: { after: null, ns: $('Write settings').first().json.keyword_namespace } }) }}

parameters.jsCode:
const cols = $('Read store').all().flatMap(i => i.json.data.collections.nodes);
const menus = $('Read store').first().json.data.menus.nodes;
const handleById = Object.fromEntries(cols.map(c => [c.id, c.handle]));
const handleOf = it => handleById[it.resourceId] || (it.url || '').match(/\/collections\/([^/?#]+)/)?.[1];
const s = $('Write settings').first().json;
const rows = Object.fromEntries($('Get copy rows').all().filter(i => i.json.handle).map(i => [i.json.handle, i.json]));
const titleOf = Object.fromEntries(cols.map(c => [c.handle, c.title]));

// Parent, children and siblings come from how the main menu is nested...
const parent = {}, kids = {};
const adopt = (h, up) => { if (h && up && h !== up && !parent[h]) { parent[h] = up; (kids[up] = kids[up] || []).push(h); } };
const walk = (items, up) => {
  for (const it of items || []) {
    const h = handleOf(it);
    adopt(h, up);
    walk(it.items, h && h !== up ? h : up);
  }
};
walk(menus.find(m => m.handle === s.tree_menu)?.items, null);
// ...and, for collections not in the menu, from their rules: "type is X and ..." sits under the collection whose only rule is "type is X".
const typePage = Object.fromEntries(cols.filter(c => c.ruleSet?.rules.length === 1 && c.ruleSet.rules[0].column === 'TYPE')
  .map(c => [c.ruleSet.rules[0].condition.toLowerCase(), c.handle]));
for (const c of cols) if (!parent[c.handle] && c.ruleSet && !c.ruleSet.appliedDisjunctively && c.ruleSet.rules.length > 1) {
  const t = c.ruleSet.rules.find(r => r.column === 'TYPE' && r.relation === 'EQUALS');
  if (t) adopt(c.handle, typePage[t.condition.toLowerCase()]);
}

const ref = h => (h && titleOf[h]) ? { handle: h, title: titleOf[h] } : null;
const empty = html => !(html || '').replace(/<[^>]+>/g, '').trim();
const vol = (c, r) => Number(r.volume || c.volume?.value || 0);

return cols
  .map(c => ({ c, r: rows[c.handle] || {} }))
  .filter(({ c, r }) => !s.skip_handles.includes(c.handle))
  .filter(({ c, r }) => ['refresh', 'failed'].includes(r.status) || (!r.status && (s.rewrite_existing || empty(c.descriptionHtml))))
  .sort((a, b) => (b.r.status === 'refresh') - (a.r.status === 'refresh') || vol(b.c, b.r) - vol(a.c, a.r))   // refreshes first, then by volume
  .slice(0, s.max_per_run)
  .map(({ c, r }) => ({ json: {
    gid: c.id, handle: c.handle, title: c.title,
    keyword: r.keyword || c.keyword?.value || c.title.toLowerCase(), other_searches: r.other_searches || '', volume: vol(c, r),
    use_ai: vol(c, r) >= s.ai_min_volume, live_html: c.descriptionHtml,
    parent: ref(parent[c.handle]),
    children: (kids[c.handle] || []).map(ref).filter(Boolean),
    siblings: (kids[parent[c.handle]] || []).filter(h => h !== c.handle).map(ref).filter(Boolean),
    vendors_all: $('Read store').first().json.data.productVendors.nodes,
  } }));

