parameters.jsCode:
const s = $('Write settings').first().json;
const picks = $('Pick collections').all().map(i => i.json);
const tally = xs => Object.entries(xs.reduce((m, x) => (m[x] = (m[x] || 0) + 1, m), {})).sort((a, b) => b[1] - a[1]);

return $input.all().map((it, i) => {
  const c = picks[i];
  const all = it.json.data?.collection?.products?.nodes || [];
  const live = all.filter(p => p.status === 'ACTIVE' && (!p.tracksInventory || p.totalInventory > 0));
  const specs = tally(live.flatMap(p => [
    ...p.metafields.nodes.map(m => `${s.spec_labels[m.key] || m.key}: ${m.value}`),   // with keys:, Shopify returns key as namespace.key
    ...p.options.filter(o => o.name !== 'Title').map(o => `${o.name}: ${o.values.join(' / ')}`),
  ])).filter(([, n]) => n >= 2).slice(0, 12).map(([spec, n]) => `${spec} (${n} products)`);
  return { json: { ...c, live: live.length, specs,
    brands: tally(live.map(p => p.vendor).filter(Boolean)).slice(0, 6).map(([v]) => v),
    products: live.slice(0, 8).map(p => p.title),
    family: [...c.children, ...(c.parent ? [c.parent] : []), ...c.siblings] } };
});

const s = $('Write settings').first().json;
const approved = $('Get copy rows').all().map(i => i.json).filter(r => r.status === 'approved' && r.intro);
const list = xs => xs.length ? xs.join(', ') : '(none)';

return $input.all().map(({ json: c }) => {
  const others = approved.filter(r => r.handle !== c.handle);
  const ex = [...others.filter(r => r.parent_handle && r.parent_handle === c.parent?.handle),
              ...others.filter(r => !r.parent_handle || r.parent_handle !== c.parent?.handle)].slice(0, 3);
  const examples = (ex.length ? ex : s.examples).map(e => `${e.title || e.handle}: ${e.intro}`).join('\n\n');
  const system = `You write category page copy for ${s.store_name}, an online store.
${s.voice}
- Describe the range. Never name a product model, model number or size.
- Open with what the buyer gets from this range. Never open with a definition.
- Name only brands from BRANDS and specs from COMMON SPECS.
- Never write a URL or a link.
- No em dashes.
- Shipping, returns and payment claims come only from STORE FACTS: ${s.store_facts}

EXAMPLE INTROS, for voice only. Never copy their sentences, brands or specs.
${examples}`;
  const prompt = `COLLECTION: ${c.title}
Target keyword: ${c.keyword}
Other searches: ${c.other_searches || '(none)'}
Parent: ${c.parent?.title || '(top level)'}
Children: ${list(c.children.map(k => k.title))}
Siblings: ${list(c.siblings.map(k => k.title))}
Live products: ${c.live}
BRANDS: ${list(c.brands)}
COMMON SPECS:
${c.specs.join('\n') || '(none)'}
PRODUCTS:
${c.products.join('\n') || '(none yet)'}

Write:
- intro: one paragraph, ${s.intro_words[0]} to ${s.intro_words[1]} words. Target keyword in the first or second sentence. Name children and siblings by their exact titles where it reads naturally.
- meta_title: 20 to 48 characters. The keyword as a plural category in Title Case, then an optional modifier from this context. No store name.
- meta_description: 130 to 155 characters. Start with Shop, Buy or Compare. End with one store fact.

Reply with only this JSON object: {"intro": "...", "meta_title": "...", "meta_description": "..."}`;
  return { json: { ...c, system, prompt } };
});

const s = $('Write settings').first().json;
const and = xs => xs.length > 1 ? xs.slice(0, -1).join(', ') + ' and ' + xs.at(-1) : xs.join('');
return $input.all().map(({ json: c }) => {
  const brands = c.brands.filter(b => b.toLowerCase() !== c.title.toLowerCase());   // a brand page names no other brand
  return { json: { ...c, output: {
    intro: brands.length ? `Shop our ${c.title} from ${and(brands)}.` : `Shop the ${c.title} range.`,
    meta_title: brands.length ? `${c.title} | ${and(brands.slice(0, 2))}` : c.title,
    meta_description: `Shop ${brands.length ? c.title + ' from ' + and(brands.slice(0, 3)) : 'the ' + c.title + ' range'} at ${s.store_name}. ${s.store_facts}`,
  } } };
});

const s = $('Write settings').first().json;
const fix = t => String(t || '').replace(/\s*[\u2014\u2013]\s*/g, ', ').replace(/\s+/g, ' ').trim();
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rx = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const has = (text, word) => new RegExp(`(^|[^\\w])${rx(word)}(?![\\w])`, 'i').test(text);
// Models wrap JSON in code fences and leave trailing commas, so read it leniently.
const readJson = t => {
  try {
    const j = JSON.parse(String(t || '').replace(/```(json)?/gi, '').replace(/,\s*([}\]])/g, '$1').trim());
    return j.output || j;
  } catch (e) { return {}; }
};

return $input.all().map((it) => {
  const c = it.json, d = c.output || readJson(c.text);
  const intro = fix(d.intro), metaDesc = fix(d.meta_description);
  const metaTitle = fix(d.meta_title).replace(new RegExp(`\\s*[|-]\\s*${rx(s.store_name)}$`, 'i'), '');
  const base = { gid: c.gid, handle: c.handle, title: c.title, keyword: c.keyword, other_searches: c.other_searches, volume: c.volume,
    parent_handle: c.parent?.handle || '', live_html: c.live_html, written_by: c.use_ai ? 'the model' : 'the template' };
  if (!intro) return { json: { ...base, intro: '', body_html: '', meta_title: '', meta_description: '', links: [],
    flags: ['no draft: ' + (c.error || 'the model returned nothing')], status: 'failed' } };   // tried again next run
  const flags = [];
  const words = intro.split(' ').filter(Boolean).length;
  if ((words < s.intro_words[0] - 10 || words > s.intro_words[1] + 10)) flags.push(`intro is ${words} words`);

  const stray = c.vendors_all.filter(v => !c.brands.includes(v) && has(intro, v));
  if (stray.length) flags.push('brands not in this collection: ' + stray.join(', '));
  const codes = [...new Set(c.products.join(' ').match(/\b(?=[A-Z0-9-]*\d)(?=[A-Z0-9-]*[A-Z])[A-Z0-9-]{4,}\b/g) || [])];
  const models = codes.filter(m => has(intro, m));
  if (models.length) flags.push('names a model: ' + models.join(', '));
  // Numbers are fine when they come from the titles, specs, brands or store facts, never from a product.
  const known = JSON.stringify([c.title, c.keyword, c.other_searches, c.family.map(f => f.title), c.specs, c.brands, s.store_facts]);
  const nums = [...new Set(intro.match(/[\w.]*\d[\w.]*/g) || [])].map(n => n.replace(/\.$/, '')).filter(n => !has(known, n));
  if (nums.length) flags.push('names a size or number: ' + nums.join(', '));
  if (metaTitle.length > 48) flags.push(`meta title is ${metaTitle.length} characters`);
  if (/\b(guide|tips|how to|explained|options)\b/i.test(metaTitle)) flags.push('meta title reads like an article');
  if (metaDesc.length < 120 || metaDesc.length > 160) flags.push(`meta description is ${metaDesc.length} characters`);

  // First mention of a related collection becomes a link; children not mentioned get a line of their own.
  let html = esc(intro), budget = s.max_links;
  const linked = [];
  for (const f of [...c.family].sort((a, b) => b.title.length - a.title.length)) {   // longest first: 4K Security Cameras before Security Cameras
    const re = new RegExp(`(^|[^\\w>])(${rx(esc(f.title))})(?![\\w<])`, 'i');
    if (budget > 0 && re.test(html)) {
      html = html.replace(re, `$1<a href="/collections/${f.handle}">$2</a>`);
      linked.push(f.handle); budget--;
    }
  }
  const missing = c.children.filter(k => !linked.includes(k.handle));
  const body = `<p>${html}</p>` + (missing.length ? `<p>Shop by type: ${missing.map(k =>
    `<a href="/collections/${k.handle}">${esc(k.title)}</a>`).join(', ')}.</p>` : '');
  const seoTitle = (metaTitle + ' | ' + s.store_name).length <= 60 ? `${metaTitle} | ${s.store_name}` : metaTitle;

  return { json: { ...base, intro, body_html: body, meta_title: seoTitle, meta_description: metaDesc,
    links: [...linked, ...missing.map(k => k.handle)], flags, status: 'review' } };
});

const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
if (Math.abs(Date.now() / 1000 - Number(h['x-slack-request-timestamp'])) > 300) throw new Error('Stale request');
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || ''; // no URLSearchParams in the Code node
const p = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' ')));
const a = p.actions[0];
return [{ json: { base: `v0:${h['x-slack-request-timestamp']}:${raw}`, expected: h['x-slack-signature'],
  action: a.action_id, handle: a.value, user: p.user.username, channel: p.channel.id, ts: p.message.ts } }];

