parameters.jsCode:
const s = $('Sort settings').first().json;
const rows = Object.fromEntries($('Sort copy rows').all().filter(i => i.json.handle).map(i => [i.json.handle, i.json]));
return $('Sort read store').all().flatMap(i => i.json.data.collections.nodes)
  .map(c => ({ c, kw: rows[c.handle]?.keyword || c.keyword?.value }))
  .filter(({ c, kw }) => kw && !s.skip_handles.includes(c.handle))
  .map(({ c, kw }) => ({ json: { gid: c.id, handle: c.handle, keyword: kw,
    other_searches: (rows[c.handle]?.other_searches || '').split(',').map(x => x.trim()).filter(Boolean) } }));

const s = $('Sort settings').first().json;
const cols = $('Collections to sort').all().map(i => i.json);
const tokens = t => [...new Set(String(t).toLowerCase().replace(/wi-?fi/g, 'wifi').split(/[^a-z0-9]+/)
  .filter(w => w && !s.stopwords.includes(w))
  .map(w => w.length > 4 && w.endsWith('ies') ? w.slice(0, -3) + 'y' : (w.length > 3 && /[^siu]s$/.test(w) ? w.slice(0, -1) : w))
  .map(w => s.synonyms[w] || w))];
const score = (kw, title) => { const k = tokens(kw), t = tokens(title); return k.length ? k.filter(w => t.includes(w)).length / k.length : 0; };
const buyable = p => p.status === 'ACTIVE' && p.featuredMedia && Number(p.priceRangeV2.minVariantPrice.amount) > 0
  && (!p.tracksInventory || p.totalInventory > 0);

return $input.all().map((it, i) => {
  const c = cols[i], col = it.json.data.collection, now = col.products.nodes;
  const ids = now.map(p => p.id);
  const byKeyword = list => list.map(p => ({ p, sc: score(c.keyword, p.title), at: ids.indexOf(p.id) }))
    .sort((a, b) => b.sc - a.sc || a.at - b.at).map(x => x.p);
  const ready = now.filter(buyable), placed = [];
  for (const kw of c.other_searches) {       // one best product per other search, in your order
    const best = ready.filter(p => !placed.includes(p)).map(p => ({ p, sc: score(kw, p.title) })).sort((a, b) => b.sc - a.sc)[0];
    if (best && best.sc >= s.min_secondary) placed.push(best.p);
  }
  const order = [...placed, ...byKeyword(ready.filter(p => !placed.includes(p))), ...byKeyword(now.filter(p => !buyable(p)))];

  // Shopify re-sorts a collection after it switches to Manual, so a switch gets this run and the moves wait for the next.
  if (col.sortOrder !== 'MANUAL') return { json: { gid: c.gid, handle: c.handle, was: col.sortOrder, switch: true, moves: [],
    page1: order.slice(0, 8).map(p => p.title), last: order.filter(p => !buyable(p)).map(p => p.title) } };
  const arr = ids.slice(), moves = [];
  order.forEach((p, pos) => {                // only the moves that change the live order
    if (arr[pos] === p.id) return;
    const at = arr.indexOf(p.id);
    if (at >= 0) arr.splice(at, 1);
    arr.splice(pos, 0, p.id);
    moves.push({ id: p.id, newPosition: String(pos) });
  });
  return { json: { gid: c.gid, handle: c.handle, was: col.sortOrder, switch: false, moves: moves.slice(0, 250), page1: order.slice(0, 8).map(p => p.title),
    last: order.filter(p => !buyable(p)).map(p => p.title) } };
});

