parameters.jsCode:
const s = $('Audit settings').first().json;   // { tree_menu, ignore: ["frontpage"], theme_linked: [] }
const cols = $('Audit read store').all().flatMap(i => i.json.data.collections.nodes).filter(c => !s.ignore.includes(c.handle));
const menus = $('Audit read store').first().json.data.menus.nodes;
const handleById = Object.fromEntries(cols.map(c => [c.id, c.handle]));
const handleOf = it => handleById[it.resourceId] || (it.url || '').match(/\/collections\/([^/?#]+)/)?.[1];
const linksTo = (html, h) => new RegExp(`href="[^"]*/collections/${h}(["?#/])`).test(html || '');

const inMenu = new Set(), parent = {};
const walk = (items, up, tree) => {
  for (const it of items || []) {
    const h = handleOf(it);
    if (h) inMenu.add(h);
    if (tree && h && up && h !== up && !parent[h]) parent[h] = up;
    walk(it.items, h && h !== up ? h : up, tree);
  }
};
for (const m of menus) walk(m.items, null, m.handle === s.tree_menu);
// Collections outside the menu sit under the page whose only rule is their type, as in the Write lane.
const typePage = Object.fromEntries(cols.filter(c => c.ruleSet?.rules.length === 1 && c.ruleSet.rules[0].column === 'TYPE')
  .map(c => [c.ruleSet.rules[0].condition.toLowerCase(), c.handle]));
for (const c of cols) if (!parent[c.handle] && c.ruleSet && !c.ruleSet.appliedDisjunctively && c.ruleSet.rules.length > 1) {
  const t = c.ruleSet.rules.find(r => r.column === 'TYPE' && r.relation === 'EQUALS');
  const up = t && typePage[t.condition.toLowerCase()];
  if (up && up !== c.handle) parent[c.handle] = up;
}

const desc = Object.fromEntries(cols.map(c => [c.handle, c.descriptionHtml]));
const today = new Date().toISOString().slice(0, 10);
const orphans = cols.filter(c => !inMenu.has(c.handle) && !s.theme_linked.includes(c.handle)
  && !cols.some(o => o.handle !== c.handle && linksTo(o.descriptionHtml, c.handle)));
const empty = cols.filter(c => inMenu.has(c.handle) && c.productsCount.count === 0);
const unlinked = Object.entries(parent).filter(([kid, up]) => kid in desc && up in desc && !linksTo(desc[up], kid));

return [
  ...orphans.map(c => ({ json: { run_date: today, handle: c.handle, issue: 'orphan', parent_handle: parent[c.handle] || '' } })),
  ...empty.map(c => ({ json: { run_date: today, handle: c.handle, issue: 'menu links to empty collection', parent_handle: '' } })),
  ...unlinked.map(([kid, up]) => ({ json: { run_date: today, handle: kid, issue: 'not linked from parent', parent_handle: up } })),
