// Parents with copy that miss a child link go back to the Write lane, once each.
const ups = [...new Set($('Find orphans').all().filter(i => i.json.issue === 'not linked from parent').map(i => i.json.parent_handle))];
return ups.map(h => ({ json: { handle: h } }));

